<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import Icon from './Icon.vue'
type PriceRow = { code: string; part: string; model: string; type: string; scope: string; amount: string; version: number; source: string; start: string }
const names = ['前挡泥板', '前大灯总成', '前轮毂', '前减震总成', '仪表总成', '后视镜', '制动手柄', '前制动盘', '座垫总成', '后尾灯总成', '转向灯', '控制器']
const amounts = ['128.00', '268.00', '386.00', '296.00', '215.80', '49.50', '58.00', '138.60', '186.00', '168.50', '62.00', '325.00']
const rows: PriceRow[] = names.map((part, index) => ({ code: `PT-${String(index + 1).padStart(5, '0')}`, part, model: index % 2 ? '示例 A · 轻行款' : '示例 A · 城市款', type: index % 3 ? '网点原始参考价' : '平台参考价', scope: index % 3 === 2 ? '示例区域一' : '全国通用', amount: amounts[index], version: index % 3 + 1, source: '示例人工维护', start: '2026-09-01' }))
const query = ref(''), type = ref(''), scope = ref(''), applied = reactive({ query: '', type: '', scope: '' }), page = ref(1), more = ref(false), loading = ref(false), state = ref('normal')
const editing = ref<PriceRow | null>(null), form = reactive({ amount: '', source: '示例人工维护', start: '2026-10-18', end: '' }), errors = reactive({ amount: '', start: '', end: '' }), confirm = ref(false), history = ref<PriceRow | null>(null)
const extra = reactive({ alias: '', brand: '', model: '', region: '', shop: '', date: '2026-10-18' })
const filtered = computed(() => state.value === 'empty' ? [] : rows.filter(row => (!applied.query || `${row.part} ${row.code} ${row.model}`.includes(applied.query)) && (!applied.type || row.type === applied.type) && (!applied.scope || (applied.scope === '全国通用' ? row.scope === applied.scope : row.scope !== '全国通用'))))
const visible = computed(() => filtered.value.slice((page.value - 1) * 6, page.value * 6))
let timer: ReturnType<typeof setTimeout> | undefined
function search() { applied.query = query.value.trim(); applied.type = type.value; applied.scope = scope.value; page.value = 1; state.value = 'normal'; loading.value = true; clearTimeout(timer); timer = setTimeout(() => { loading.value = false }, 360) }
function reset() { query.value = ''; type.value = ''; scope.value = ''; Object.assign(applied, { query: '', type: '', scope: '' }); page.value = 1; state.value = 'normal' }
function edit(row: PriceRow) { editing.value = row; Object.assign(form, { amount: '', source: '示例人工维护', start: '2026-10-18', end: '' }); Object.assign(errors, { amount: '', start: '', end: '' }) }
function validate() {
  errors.amount = !/^\d+(\.\d{1,2})?$/.test(form.amount) || !/[1-9]/.test(form.amount) ? '请输入大于 0 的金额，最多保留 2 位小数。' : ''
  errors.start = !form.start ? '请选择生效开始日。' : form.start <= (editing.value?.start || '') ? '新开始日必须晚于当前版本开始日。' : ''
  errors.end = form.end && form.end < form.start ? '截止日不能早于开始日。' : ''
  if (!errors.amount && !errors.start && !errors.end) confirm.value = true
}
function saveDemo() { confirm.value = false; ElMessage.success('新版本确认反馈已演示，未更改价格数据。') }
function stateChanged() { clearTimeout(timer); loading.value = state.value === 'loading'; page.value = 1 }
onBeforeUnmount(() => clearTimeout(timer))
</script>

<template>
  <div class="table-page page-padding">
    <template v-if="!editing"><header class="module-heading"><div><p class="overline">价格资料</p><h1>价格数据库</h1></div><div class="heading-actions"><el-button @click="ElMessage.info('导入沿用现有预览、核对与确认流程。此轮展示列表和版本表单。')"><Icon name="upload" :size="16"/>Excel / CSV 导入</el-button><el-button type="primary" @click="ElMessage.info('本轮表单样板展示“新版本”，请从价格行进入。新增价格仍沿用当前完整页面。')"><Icon name="plus" :size="16"/>新增价格</el-button></div></header>
      <nav class="catalogue-nav" aria-label="价格基础资料"><button v-for="name in ['价格候选', '品牌', '车型', '标准配件', '配件别名', '数据来源', '车型适配', '导入批次']" :key="name" :class="{ selected: name === '价格候选' }" @click="name !== '价格候选' && ElMessage.info(`${name}沿用现有入口，本轮展示价格候选样板。`)">{{ name }}</button></nav>
      <section class="surface filter-surface"><form class="price-filters" @submit.prevent="search"><label class="filter-query"><span>配件编号 / 名称</span><el-input v-model="query" clearable placeholder="如 PT-00001、前挡泥板" aria-label="配件编号或名称"><template #prefix><Icon name="search" :size="16"/></template></el-input></label><label><span>价格类型</span><el-select v-model="type" clearable placeholder="全部类型" aria-label="价格类型"><el-option label="网点原始参考价" value="网点原始参考价"/><el-option label="平台参考价" value="平台参考价"/></el-select></label><label><span>适用范围</span><el-select v-model="scope" clearable placeholder="全部范围" aria-label="适用范围"><el-option label="全国通用" value="全国通用"/><el-option label="区域" value="区域"/></el-select></label><div class="filter-actions"><el-button native-type="submit" type="primary">查询</el-button><el-button @click="reset">重置</el-button><button class="text-button" type="button" :aria-expanded="more" @click="more = !more">更多筛选<Icon name="down" :size="14" :class="{ rotated: more }"/></button></div></form>
        <div v-if="more" class="extra-filters"><label v-for="item in [{ key: 'alias', title: '别名（精确）' }, { key: 'brand', title: '品牌 ID' }, { key: 'model', title: '车型 ID' }, { key: 'region', title: '区域 ID' }, { key: 'shop', title: '网点 ID' }]" :key="item.key"><span>{{ item.title }}</span><el-input v-model="extra[item.key as keyof typeof extra]" :aria-label="item.title"/></label><label><span>适用自然日</span><el-input v-model="extra.date" type="date" aria-label="适用自然日"/></label><p class="small-note">更多筛选展示控件样式，样板查询仅按上方配件、类型和范围过滤。正式查询口径保持不变。</p></div>
      </section>
      <section class="surface price-surface"><header class="section-heading"><h2>参考价格 <span class="count">{{ filtered.length }}</span></h2><div class="table-demo-controls"><span>样板状态</span><select v-model="state" aria-label="样板状态" @change="stateChanged"><option value="normal">正常</option><option value="loading">加载中</option><option value="empty">空结果</option><option value="error">加载失败</option></select><span class="unit-label">金额单位：元</span></div></header>
        <div v-if="loading" class="table-skeleton" aria-busy="true" aria-label="正在加载价格"><div v-for="i in 6" :key="i"><span/><span/><span/></div></div>
        <div v-else-if="state === 'error'" class="empty-state error-state" role="alert"><Icon name="file" :size="28"/><h3>价格加载失败</h3><p>请检查连接后重试。</p><el-button @click="search">重新加载</el-button></div>
        <template v-else><el-table :data="visible" row-key="code" class="price-table" empty-text="暂无符合条件的价格" highlight-current-row><el-table-column label="配件" min-width="168" fixed><template #default="{ row }"><div class="part-cell"><strong>{{ row.part }}</strong><small class="mono">{{ row.code }}</small></div></template></el-table-column><el-table-column prop="model" label="品牌 / 车型" min-width="150"/><el-table-column prop="type" label="价格类型" min-width="140"/><el-table-column prop="scope" label="适用范围" min-width="124"/><el-table-column label="金额" min-width="110" align="right"><template #default="{ row }"><strong class="price-amount mono">{{ row.amount }}</strong></template></el-table-column><el-table-column label="生效区间" min-width="138"><template #default="{ row }"><div class="part-cell"><span class="mono">{{ row.start }}</span><small>持续有效</small></div></template></el-table-column><el-table-column label="版本" width="64"><template #default="{ row }"><span class="version-tag mono">v{{ row.version }}</span></template></el-table-column><el-table-column prop="source" label="数据来源" min-width="130"/><el-table-column label="操作" width="140" fixed="right"><template #default="{ row }"><div class="table-actions"><button class="text-button" @click="history = row as PriceRow">详情 / 历史</button><button class="text-button" @click="edit(row as PriceRow)">新版本</button></div></template></el-table-column><template #empty><div class="empty-state"><Icon name="search" :size="26"/><h3>暂无符合条件的价格</h3><button class="text-button" @click="reset">清除筛选</button></div></template></el-table></template>
        <footer class="price-pagination"><span>共 {{ filtered.length }} 条</span><el-pagination v-model:current-page="page" :page-size="6" :total="filtered.length" layout="prev, pager, next" :disabled="loading || state === 'error'"/><span>6 条 / 页</span></footer>
      </section><footer class="page-footnote">e保 · 保险协作台<span>价格更新始终新增版本，历史记录保留</span></footer>
    </template>
    <template v-else><button class="text-button back-to-table" @click="editing = null"><Icon name="back" :size="16"/>返回价格库</button><header class="module-heading"><div><p class="overline">价格版本</p><h1>创建新价格版本</h1></div><span class="version-label">{{ editing.code }}</span></header><div class="editor-layout"><section class="surface version-editor"><header class="section-heading"><h2>{{ editing.part }}</h2><span class="status neutral">{{ editing.type }}</span></header><div class="version-context"><span>{{ editing.model }}<span class="tiny-divider">/</span>{{ editing.scope }}</span><span>当前 v{{ editing.version }} <strong class="mono">¥ {{ editing.amount }}</strong></span></div><form class="version-form" @submit.prevent="validate"><label class="wide"><span>金额（元）<span class="required">*</span></span><el-input v-model="form.amount" inputmode="decimal" maxlength="16" placeholder="输入新的参考金额" :class="{ 'invalid-field': errors.amount }" aria-label="新版本金额" @input="errors.amount = ''"><template #prefix>¥</template></el-input><small v-if="errors.amount" class="field-error" role="alert">{{ errors.amount }}</small></label><label class="wide"><span>数据来源<span class="required">*</span></span><el-select v-model="form.source" aria-label="数据来源"><el-option label="示例人工维护" value="示例人工维护"/></el-select></label><label><span>生效开始日<span class="required">*</span></span><el-input v-model="form.start" type="date" aria-label="生效开始日" :class="{ 'invalid-field': errors.start }"/><small v-if="errors.start" class="field-error" role="alert">{{ errors.start }}</small></label><label><span>截止日 <span class="optional">可空</span></span><el-input v-model="form.end" type="date" aria-label="截止日" :class="{ 'invalid-field': errors.end }"/><small v-if="errors.end" class="field-error" role="alert">{{ errors.end }}</small></label><p class="form-note wide">新版本生效后，无期限旧版本截止至前一天，历史记录保留。</p><div class="form-actions wide"><el-button @click="editing = null">取消</el-button><el-button type="primary" native-type="submit">保存新版本<Icon name="arrow" :size="16"/></el-button></div></form></section><aside class="version-aside glass"><Icon name="history" :size="24"/><h3>当前版本</h3><strong class="current-price mono">¥ {{ editing.amount }}</strong><dl><div><dt>版本</dt><dd>v{{ editing.version }}</dd></div><div><dt>开始日</dt><dd class="mono">{{ editing.start }}</dd></div><div><dt>截止日</dt><dd>持续有效</dd></div><div><dt>来源</dt><dd>{{ editing.source }}</dd></div></dl><span class="small-note">仅供核对，原版本不可覆盖。</span></aside></div></template>
    <el-dialog v-model="confirm" title="确认保存新版本" width="460px"><p class="dialog-copy">当前无期限旧版本将截止至新开始日前一天，新版本的金额、来源与创建记录将保留。</p><div class="confirm-amount mono">¥ {{ form.amount }}</div><p class="small-note">本次仅演示确认反馈，不提交价格数据。</p><template #footer><el-button @click="confirm = false">返回核对</el-button><el-button type="primary" @click="saveDemo">演示保存</el-button></template></el-dialog>
    <el-dialog :model-value="Boolean(history)" title="价格详情 / 历史" width="580px" @close="history = null"><template v-if="history"><h3>{{ history.part }} <span class="version-label">{{ history.code }}</span></h3><div class="history-version"><span>v{{ history.version }}</span><strong class="mono">¥ {{ history.amount }}</strong><span>{{ history.start }} 至今</span></div><p class="small-note">展示当前示例版本；正式页面保留完整历史与来源记录。</p></template></el-dialog>
  </div>
</template>
